import logging
from robot.libraries.BuiltIn import BuiltIn, RobotNotRunningError
from ute_common_abstract_core import scope
from taf.internal.aliasing import aliasing_scope
from taf.ul.power_ue.devices.device_class import PowerUeDevice
from taf.ul.power_ue.factory import create_device
from taf.ul.power_ue.exception import CapabilitiesMismatched
from taf.ul.power_ue.store import DTvsUE
from taf.ul.power_ue.throughput import Aasyslog


class power_ue(object):
    """
    Power UE supporting Devices:

    * FastMile
    * Samsung
        * Samsung S21
        * Samsung S22
        * Samsung S23
    * Harmony
        * Honor 30s
    * MTK
        * MediaTek MT6885 M70
    * Xiaomi
        * Xiaomi 12 Pro
    * Qualcomm
        * Qualcomm CPE
    * HuaweiAndroid
        * Huawei Mate pro 30
    """

    ROBOT_LIBRARY_SCOPE = "TEST SUITE"
    ROBOT_LISTENER_API_VERSION = 2
    SCOPE_OWNER = "robot_api"

    lookup_handler, configured_power_ue_device = aliasing_scope(
        name=__name__, lookup_arg="ue", lookup_type=PowerUeDevice
    )

    def __init__(self):
        self.ROBOT_LIBRARY_LISTENER = self
        self.logger = logging.getLogger("power_ue")
        self.tl = self._get_robot_tl_variable()
        self.robot_logs_dir = self._get_robot_variable("OUTPUT_DIR")
        self._syslog = Aasyslog(self.tl, self.robot_logs_dir)
        DTvsUE().init_store()

    def _get_robot_tl_variable(self):
        tl = self._get_robot_variable("tl")
        if not tl:
            raise EnvironmentError(
                "taf.ul.power_ue based on taf.config.testline configuration variable. "
                "Please ensure you are using testline configuration correctly"
            )
        return tl

    @staticmethod
    def _get_robot_variable(variable):
        """
        Return the given variable value from robot.

        :param variable: name of variable
        :return: Value of variable and None if variable is not defined
        """
        try:
            return BuiltIn().get_variable_value("${{{}}}".format(variable))
        except RobotNotRunningError:
            return None

    def _look_up_ue_selector(self, ue_index, capabilities=None):
        if capabilities:
            for ue in self.tl.ues:
                if capabilities in ue.capabilities:
                    return ue, ue.capabilities[-1]
            raise CapabilitiesMismatched("Please correct capabilities parameter")
        return self.tl.ues[ue_index], self.tl.ues[ue_index].capabilities[-1]

    def prepare_ue(
        self,
        ue_alias,
        ue_index=0,
        capabilities=None,
    ):
        """
        Prepare UE for L3 call.

        :param ue_alias: str, store PowerUeDevice object by ue_alias
        :param ue_index: Optional[int], The list index from tl.ues[], it will use the index UE for reserve
        :param capabilities: Optional[str], capabilities for reserve ue
        :return: None

        """
        ue_config, ue_selector = self._look_up_ue_selector(ue_index, capabilities)
        power_ue_device = create_device(
            ue_selector=ue_selector,
            tl=self.tl,
            ue_config=ue_config,
            robot_logs_dir=self.robot_logs_dir,
        )
        self.configured_power_ue_device.add(power_ue_device, ue_alias)

        return power_ue_device.prepare(ue_alias=ue_alias)

    @lookup_handler.implicit_lookup
    def teardown_ue(
        self,
        ue=None,
    ):
        """
        Teardown UE after test finished.

        :param ue: Optional[Union[str,PowerUeDevice]], can be a string name alias or PowerUeDevice object
        :return: None
        """
        DTvsUE().init_store()
        return ue.teardown()

    @lookup_handler.implicit_lookup
    def ue_attach(
        self,
        timeout=30,
        ue=None,
    ):
        """
        Attach UE for L3 call.

        :param ue: Optional[Union[str,PowerUeDevice]], can be a string name alias or PowerUeDevice object
        :param timeout: Optional[float], timeout for verify attach procedure, 10 as default means 10s.
        :return: None
        """
        return ue.attach(timeout=timeout)

    @lookup_handler.implicit_lookup
    def verify_ue_attach(
        self,
        timeout=60,
        apn=None,
        pci=None,
        ue=None,
        cell_id=None,
    ):
        """
        Verify attach result when plugin verify itself insufficiently.

        :param ue: Optional[Union[str,PowerUeDevice]], can be a string name alias or PowerUeDevice object
        :param timeout: Optional[float], timeout for verify attach procedure, 60 as default means 60s.
        :param apn: Optional[str], apn name, None as default.
        :param pci: Optional[int], pci check attach result, None as default.
        :param cell_id: Optional[int], cell_id check attach result, None as default. It is the "NR cell ID" which means nrCellIdentity
        :return: None
        """
        return ue.verify_attach(timeout=timeout, pci=pci, apn=apn, cell_id=cell_id)

    @lookup_handler.implicit_lookup
    def ue_reboot(
        self,
        timeout=180,
        ue=None,
    ):
        """
        Detach UE for L3 call.

        :param ue: Optional[Union[str,PowerUeDevice]], can be a string name alias or PowerUeDevice object
        :param timeout: Optional[float], timeout for reboot procedure, 180 as default means 180s.
        :return: None
        """
        return ue.reboot(timeout=timeout)

    @lookup_handler.implicit_lookup
    def ue_detach(
        self,
        ue=None,
    ):
        """
        Detach UE for L3 call.

        :param ue: Optional[Union[str,PowerUeDevice]], can be a string name alias or PowerUeDevice object
        :return: None
        """
        return ue.detach()

    @lookup_handler.implicit_lookup
    def start_traffic(
        self,
        dt_name,
        direction,
        duration=10,
        throughput=10.0,
        protocol="udp",
        iperf_port=None,
        iperf_options=None,
        check_dt_alive_timeout=None,
        ue=None,
        apn=None,
    ):
        """
        Start data transfer for L3 call.

        :param dt_name: str, alias name for created data transfer.
        :param direction: str, traffic direction, 'ul', 'dl', 'simultaneous_ul_dl'.
        :param duration: Optional[int], Duration of traffic, 10 as default means 10s.
        :param throughput: Optional[float], Bandwidth to send in Mbps!!
        :param protocol: Optional[str], Traffic protocol type. E.G udp/tcp, 'udp' as default.
        :param iperf_port: Optional[str], port number used for traffic start via iperf, None as default.
        :param iperf_options: Optional[dict], iperf parameter options, None as default.
        :param check_dt_alive_timeout: Optional[int], time after start traffic to check dt alive, None as default.
        :param ue: Optional[Union[str,PowerUeDevice]], can be a string name alias or PowerUeDevice object
        :return: None
        """
        throughput = float(throughput)
        DTvsUE().store_ue(dt_name=dt_name, ue=ue)
        return ue.start_traffic(
            dt_name=dt_name,
            direction=direction,
            throughput=throughput,
            duration=duration,
            protocol=protocol,
            iperf_port=iperf_port,
            iperf_options=iperf_options,
            check_dt_alive_timeout=check_dt_alive_timeout,
            apn=apn,
        )

    @staticmethod
    def stop_traffic(
        dt_name,
    ):
        """
        Stop data transfer for L3 call.

        :param dt_name: str, alias name for created data transfer.
        :return: None
        """
        ue = DTvsUE().get_ue(dt_name=dt_name)
        return ue.stop_traffic(dt_name=dt_name)

    def collect_syslog_for_throughput(
        self,
        omit=60,
        end=660,
        gnb_index=0,
        du_index=0,
        common_unit_index=0,
        stop_after_duration=True,
        alias="syslog_0",
    ):
        """
        Collect throughput for given duration.

        :param omit: it is a delay in seconds to start counting the tput ex.
                     '20' - 1st 20 seconds of datatransfer will be omitted.
        :param end: it is end time in seconds to stop counting the tput ex.
                    '40' - it takes into account data till 40 second of transfer.
        :param gnb_index: Optional[str], gnb index in tl to collect log.
        :param du_index: Optional[str], du index in gnb to collect log.
        :param common_unit_index: Optional[str], common unit index in du to collect log.
        :param stop_after_duration: Optional[bool], if teardown after duration. E.G True / False.
        :param alias: Optional[str], alias of collected log info.
            To identify if there will be multiple times of collect throughput. Default is `syslog_0`
        :return: dict, {"log_path": ["xxx/xxxx/2023xxxx.txt"], "omit": 60, "end": 660, "alias": "syslog_0"}
        """
        return self._syslog.collect(
            omit=omit,
            end=end,
            gnb_index=gnb_index,
            du_index=du_index,
            common_unit_index=common_unit_index,
            stop_after_duration=stop_after_duration,
            alias=alias,
        )

    def check_unidirectional_throughput_from_syslog(
        self,
        direction,
        theoretical_throughput,
        average_tolerance=0.95,
        minimum_tolerance=0.8,
        nrcellids=None,
        ca=False,
        enable_chart_generation=True,
        customized_chart_file_name="",
        alias="syslog_0",
    ):
        """
        Check unidirectional Throughput via syslog throughput output. Raise UnexpectedCellsThroughputError
        when target throughput values lower than tolerance.

        :param direction: str, direction of the target traffic to be checked. E.G UL / DL.
        :param theoretical_throughput: float, target throughput value.(theory value) unit in Mbps!!
            E.G 10 means 10Mbit / sec.
        :param average_tolerance: Optional[str], acceptable percent. E.G 95%.
        :param minimum_tolerance: Optional[str], minimum percentage, E.G 85%.
        :param nrcellids: Optional[list], NR cell ID list.  E.G [9633793]
        :param ca: Optional[Bool], actCarrierAggregation,
                   Define the chart should show data of each cell or combine togather.
        :param enable_chart_generation: Optional[Bool], generate image or not E.G True / False
        :param customized_chart_file_name: Optional[str], customized log name
        :param alias: Optional[str], alias of collected log info.
            To identify if there will be multiple times of collect throughput. Default is `syslog_0`

        :return: Analyzed throughput data that were used for checking throughput.
        """

        return self._syslog.check_unidirectional_throughput(
            direction=direction,
            nrcellids=nrcellids,
            theoretical_throughput=theoretical_throughput,
            average_tolerance=average_tolerance,
            minimum_tolerance=minimum_tolerance,
            ca=ca,
            enable_chart_generation=enable_chart_generation,
            customized_chart_file_name=customized_chart_file_name,
            alias=alias,
        )

    def check_bidirectional_throughput_from_syslog(
        self,
        ul_theoretical_throughput,
        dl_theoretical_throughput,
        average_tolerance=0.95,
        minimum_tolerance=0.8,
        nrcellids=None,
        ca=False,
        enable_chart_generation=True,
        customized_chart_file_name="",
        alias="syslog_0",
    ):
        """
        Check bidirectional Throughput by check output from syslog. Raise UnexpectedCellsThroughputError
        when target throughput values lower than tolerance.

        :param ul_theoretical_throughput: float, target throughput value.(theory value) unit in Mbps!!
                                     E.G 10 means 10Mbit / sec.
        :param dl_theoretical_throughput: float, target throughput value.(theory value) unit in Mbps!!
                                     E.G 10 means 10Mbit / sec.
        :param average_tolerance: Optional[str], acceptable percent. E.G 95%.
        :param minimum_tolerance: Optional[str], minimum percentage, E.G 85%.
        :param nrcellids: Optional[list], cell ID list.  E.G [9633793]
        :param ca: Optional[Bool], actCarrierAggregation, parameter for aasyslog checking.
              Define whether the throughput should be checked as CarrierAggregation traffic
        :param enable_chart_generation: Optional[Bool], generate image or not E.G True / False
        :param customized_chart_file_name: Optional[str], customized log name
        :param alias: Optional[str], alias of collected log info.
            To identify if there will be multiple times of collect throughput. Default is `syslog_0`

        Returns: Analyzed throughput data that were used for checking throughput.

        """

        return self._syslog.check_bidirectional_throughput(
            nrcellids=nrcellids,
            ul_theoretical_throughput=ul_theoretical_throughput,
            dl_theoretical_throughput=dl_theoretical_throughput,
            average_tolerance=average_tolerance,
            minimum_tolerance=minimum_tolerance,
            ca=ca,
            enable_chart_generation=enable_chart_generation,
            customized_chart_file_name=customized_chart_file_name,
            alias=alias,
        )

    @staticmethod
    def check_unidirectional_throughput(
        dt_name,
        direction,
        theoretical_throughput,
        average_tolerance="0.95",
        minimum_tolerance="0.8",
        omit=60,
        end=660,
    ):
        """
        Check unidirectional Throughput.

        :param dt_name: str, alias name for created data transfer.
        :param direction: str, direction of the target traffic to be checked. E.G UL / DL.
        :param theoretical_throughput: float, target throughput value.(theory value) unit in Mbps!!
            E.G 10 means 10Mbit / sec.
        :param average_tolerance: Optional[str], acceptable percent. E.G 95%.
        :param minimum_tolerance: Optional[str], minimum percentage, E.G 85%.
        :param omit: it is a delay in seconds to start counting the tput ex.
                '60' - 1st 20 seconds of datatransfer will be omitted.
        :param end: it is end time in seconds to stop counting the tput ex.
                '660' - it takes into account data till 660 second of transfer.

        :return: Analyzed throughput data that were used for checking throughput.
        """
        ue = DTvsUE().get_ue(dt_name=dt_name)
        return ue.check_unidirectional_throughput(
            dt_name=dt_name,
            direction=direction,
            theoretical_throughput=float(theoretical_throughput),
            average_tolerance=average_tolerance,
            minimum_tolerance=minimum_tolerance,
            omit=omit,
            end=end,
        )

    @staticmethod
    def check_bidirectional_throughput(
        dt_name,
        ul_theoretical_throughput,
        dl_theoretical_throughput,
        average_tolerance="0.95",
        minimum_tolerance="0.8",
        omit=60,
        end=660,
    ):
        """
        Check bidirectional Throughput. E.G simultaneous_ul_dl in taf.ue

        :param dt_name: str, alias name for created data transfer.
        :param ul_theoretical_throughput: float, target throughput value.(theory value) unit in Mbps!!
                                     E.G 10 means 10Mbit / sec.
        :param dl_theoretical_throughput: float, target throughput value.(theory value) unit in Mbps!!
                                     E.G 10 means 10Mbit / sec.
        :param average_tolerance: Optional[str], acceptable percent. E.G 95%.
        :param minimum_tolerance: Optional[str], minimum percentage, E.G 85%.
        :param omit: it is a delay in seconds to start counting the tput ex.
                '60' - 1st 20 seconds of datatransfer will be omitted.
        :param end: it is end time in seconds to stop counting the tput ex.
                '660' - it takes into account data till 660 second of transfer.

        Returns: Analyzed throughput data that were used for checking throughput.

        """
        ue = DTvsUE().get_ue(dt_name=dt_name)
        return ue.check_bidirectional_throughput(
            dt_name=dt_name,
            ul_theoretical_throughput=float(ul_theoretical_throughput),
            dl_theoretical_throughput=float(dl_theoretical_throughput),
            average_tolerance=average_tolerance,
            minimum_tolerance=minimum_tolerance,
            omit=omit,
            end=end,
        )

    # ---  Robot callbacks  ---

    def _start_suite(self, name, attrs):
        self.logger.info("Robot TS start '{}'".format(name))
        self.logger.info('New scope "{}" created for a new testsuite'.format(name))
        scope.start_new_scope(name=name, owner=self.SCOPE_OWNER)

    def _start_test(self, name, attrs):
        self.logger.info("Robot TC start '{}'".format(name))
        self.logger.info('New scope "{}" created for a new test'.format(name))
        scope.start_new_scope(name=name, owner=self.SCOPE_OWNER)

    def _end_suite(self, name, attrs):
        """
        At the end of Test Suite reserved UEs are released

        :param name: name from robot
        :param attrs: attributes from robot
        :return: None
        """
        self.logger.info("Robot TS end   '{}'".format(name))
        scope.notify_scope_owner_changed(owner=self.SCOPE_OWNER)
        self.logger.info(
            "Suite end, stopping of current scope: {}".format(scope.current_scope())
        )
        scope.end_current_scope(owner=self.SCOPE_OWNER)

    def _end_test(self, name, attrs):
        """
        At the end of test case data transfers are cleared

        :param name: name from robot
        :param attrs: attributes from robot
        :return: None
        """
        self.logger.info("Robot TC end   '{}'".format(name))
        scope.notify_scope_owner_changed(owner=self.SCOPE_OWNER)
        self.logger.info(
            "Test end, stopping of current scope: {}".format(scope.current_scope())
        )
        scope.end_current_scope(owner=self.SCOPE_OWNER)
